package com.fixmer.mared.technology.workspace.live122;
import com.fixmer.mared.gui2.framework.screen.MaredScreen;
import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
final class WorkspaceInbox131 extends MaredScreen {
    private final Screen previous;private int page;private String state="";
    WorkspaceInbox131(Screen previous){super(WorkspaceScreen122.tr("inbox131"));this.previous=previous;}
    @Override protected void init(){int w=Math.min(720,width-24),x=(width-w)/2,rows=Math.max(1,(height-100)/36);var inbox=WorkspaceSocial131.inbox();state=signature();page=Math.min(page,Math.max(0,(inbox.size()-1)/rows));for(int n=0;n<rows&&page*rows+n<inbox.size();n++){var row=inbox.get(page*rows+n);var label=Component.empty().append(WorkspaceScreen122.tr("notice."+row[2])).append(" · "+row[5]+" · "+row[4]);addRenderableWidget(WorkspaceButton131.builder(label,b->WorkspaceSocial131.openOffer(row[0],this)).bounds(x,44+n*36,w,28).build());}addRenderableWidget(WorkspaceButton131.builder(Component.literal("<"),b->{page--;rebuildWidgets();}).bounds(x,height-28,40,20).build()).active=page>0;addRenderableWidget(WorkspaceButton131.builder(WorkspaceScreen122.tr("back"),b->onClose()).bounds(x+46,height-28,w-92,20).build());addRenderableWidget(WorkspaceButton131.builder(Component.literal(">"),b->{page++;rebuildWidgets();}).bounds(x+w-40,height-28,40,20).build()).active=(page+1)*rows<inbox.size();}
    private String signature(){return String.join("\n",WorkspaceSocial131.inbox().stream().map(row->String.join("|",row)).toList());}
    @Override public void tick(){if(!state.equals(signature()))rebuildWidgets();}@Override public void onClose(){minecraft.setScreen(previous);}@Override public boolean isPauseScreen(){return false;}@Override public void render(GuiGraphics g,int mx,int my,float dt){g.fill(0,0,width,height,com.fixmer.mared.technology.editor.GenesisEditorVisuals.bg());g.drawCenteredString(font,title,width/2,14,com.fixmer.mared.technology.editor.GenesisEditorVisuals.text());if(WorkspaceSocial131.inbox().isEmpty())g.drawCenteredString(font,WorkspaceScreen122.tr("inbox_empty131"),width/2,80,0xFFB6C1D1);super.render(g,mx,my,dt);}
}
